 vmatch([[('ብክለት','ማቆሸሽ'),('መበስበስ','መፈራረስ (መሞት)'),('ተውሳክ','በሽታ አምጪ ረቂቅ ነፍሳት')],[('ፀአዳ','በጣም ነጭ'),('ጨፍጋጋ','የተከፋ'),('ማፍላት','እስኪንተከተክ ማሞቅ')]]),
