 notes(('Obeying traffic rules saves lives; adverbs tell how, when and where actions happen.','የትራፊክ ሕግን ማክበር ሕይወት ያድናል፤ ተውሳከ ግሶች ድርጊት እንዴት፣ መቼና የት እንደተፈጸመ ይነግራሉ።'),
  [('Drive carefully; do not overload or drink and drive.','በጥንቃቄ አሽከርክሩ፤ ከአቅም በላይ አትጫኑ፣ ሰክራችሁ አትንዱ።'),('Pedestrians use the zebra crossing.','እግረኞች የእግረኛ ማቋረጫ ይጠቀማሉ።'),('Adverbs: በጥንቃቄ, በችኮላ, ትናንት, ክፉኛ.','ተውሳከ ግሶች፦ በጥንቃቄ፣ በችኮላ፣ ትናንት፣ ክፉኛ።'),('Descriptive paragraphs paint pictures with words.','ሥዕላዊ አንቀጽ በቃላት ሥዕል ይስላል።')],
  [('አሽከርካሪ','driver','መኪና የሚነዳ'),('ቦሎ','vehicle inspection','የመኪና ዓመታዊ ምርመራ'),('ጥቅስ','slogan','አጭር ምክር አዘል ጽሑፍ')],('Speed kills; patience saves.','ፍጥነት ይገድላል፤ ትዕግሥት ያድናል።'),
  [(('Write one traffic slogan','አንድ የትራፊክ መፈክር ጻፉ'),'ፍጥነት ይገድላል!'),(('Add an adverb: ልጁ ___ ተሻገረ።','ተውሳከ ግስ ጨምሩ፦ ልጁ ___ ተሻገረ።'),'በጥንቃቄ')],
  (('Safety slogan stickers','የደህንነት መፈክር ተለጣፊዎች'),('Taxi owners put slogans in their vehicles. Design safety stickers and offer them to local drivers.','የታክሲ ባለቤቶች በመኪናቸው ጥቅሶችን ይለጥፋሉ። የደህንነት ተለጣፊዎችን ንደፉና ለአካባቢው አሽከርካሪዎች አቅርቡ።'),
   [('Write 5 short, clever slogans.','5 አጭርና ብልህ መፈክሮችን ጻፉ።'),('Decorate each on card.','እያንዳንዱን በካርድ ላይ አስጊጡ።'),('Ask the traffic police for advice.','የትራፊክ ፖሊስን ምክር ጠይቁ።'),('Give them to drivers with a smile.','በፈገግታ ለአሽከርካሪዎች ስጡ።')])),
