# 10 ቃላዊ ሥነጽሑፍ
U(10,('Oral literature','ቃላዊ ሥነጽሑፍ'),[
 read('ዝርዝሩ',['በድሮ ጊዜ "እንዳሉት" የሚባል ሞኝ አገልጋይ ነበር። ጌታው ያዘዘውን ብቻ ይሠራል፤ ራሱ አስቦ ምንም አያደርግም።','አንድ ቀን ጌታው በፈረስ፣ እሱ በእግር ሲጓዙ የጌታው የገንዘብ ቦርሳ መንገድ ላይ ወደቀ። እንዳሉት አይቶ አለፈው። ጌታው ሲጠይቁት "አይቻለሁ፤ ግን አንሳ አላሉኝም" አለ።','ጌታውም ተናደው የሚወድቀውን ሁሉ እንዲያነሳ የሚገልጽ ዝርዝር ጻፉለት። ተረቱ ማሰብና ማመዛዘን እንደሚያስፈልግ ያስተምራል።'],[
  A('What was the servant called?','አገልጋዩ ምን ይባል ነበር?',['እንዳሉት','ጌታው','ፈረሰኛ']),A('What fell on the road?','መንገድ ላይ የወደቀው ምንድን ነው?',['የገንዘብ ቦርሳ','ፈረስ','መጽሐፍ']),
  A('Why didn\'t the servant pick it up?','አገልጋዩ ለምን አላነሳውም?',['"አንሳ" አልተባለም','ስለደከመው','ስላላየው']),A('The tale teaches us to…','ተረቱ የሚያስተምረው…',['ማሰብና ማመዛዘን','ሁልጊዜ መተኛት','ጌታን መዋሸት'])]),
 gq(('Riddles (እንቆቅልሽ)','እንቆቅልሽ'),('Riddles are a game of oral literature: "እንቆቅልሽ!" — "ምን አውቅልህ!" Guess the answer.','እንቆቅልሽ የቃል ሥነጽሑፍ ጨዋታ ነው፦ "እንቆቅልሽ!" — "ምን አውቅልህ!" መልሱን ገምቱ።'),[
  A('It carries its house on its back.','ቤቷን በጀርባዋ ተሸክማ ትሄዳለች።',['ቀንድ አውጣ','ዶሮ','ወፍ']),A('It has teeth but never eats.','ጥርስ አለው አይበላም።',['ማበጠሪያ','አንበሳ','ሕፃን']),A('It has no legs but it runs.','እግር የለውም ይሮጣል።',['ወንዝ (ውኃ)','ዛፍ','ድንጋይ']),A('The lamp of the night sky.','የሌሊት ሰማይ መብራት።',['ጨረቃ','ፀሐይ','ደመና'])]),
 match(('Proverbs and their meaning','ምሳሌያዊ አነጋገሮችና ፍቻቸው'),('Proverbs give wise advice in few words.','ምሳሌያዊ አነጋገሮች በጥቂት ቃላት ጥበብ ያለው ምክር ይሰጣሉ።'),[[('ሲበዛ ማርም ይመራል','ማንኛውም ነገር ሲበዛ ይጎዳል'),('ድር ቢያብር አንበሳ ያስር','አንድነት ኃይል ነው'),('ያልሠራ አይብላ','ሳይሠሩ መብላት አይገባም')],[('ውኃ ቢወቅጡት እምቦጭ','ፍሬ የሌለው ድካም'),('ቀስ በቀስ እንቁላል በእግሩ ይሄዳል','ትዕግሥት ውጤት ያመጣል'),('ሠርግና ሞት አንድ ነው','ደስታም ኀዘንም ሳይጠበቅ ይመጣል')]]),
 gq(('Direct and indirect objects','ቀጥተኛና ኢቀጥተኛ ተሳቢ'),('In "አዜብ ለእናቷ ብር ላከች", ብር is the direct object (what was sent) and ለእናቷ is the indirect object (to whom).','በ"አዜብ ለእናቷ ብር ላከች" ውስጥ ብር ቀጥተኛ ተሳቢ (የተላከው)፣ ለእናቷ ኢቀጥተኛ ተሳቢ (ለማን) ነው።'),[
  A('"ሀዋ ለልጇ ልብስ ገዛች" — direct object?','"ሀዋ ለልጇ ልብስ ገዛች" — ቀጥተኛ ተሳቢው?',['ልብስ','ለልጇ','ሀዋ']),A('"ሙስጠፋ ለእህቱ መጽሐፍ ሸለማት" — indirect object?','"ሙስጠፋ ለእህቱ መጽሐፍ ሸለማት" — ኢቀጥተኛ ተሳቢው?',['ለእህቱ','መጽሐፍ','ሙስጠፋ']),A('"የኑስ ለአባቱ ደብዳቤ ጻፈ" — direct object?','"የኑስ ለአባቱ ደብዳቤ ጻፈ" — ቀጥተኛ ተሳቢው?',['ደብዳቤ','ለአባቱ','የኑስ']),A('The indirect object usually starts with…','ኢቀጥተኛ ተሳቢ ብዙ ጊዜ የሚጀምረው በ…',['ለ-','በ-','ከ-'])])],
 [A('Oral literature is passed on…','ቃላዊ ሥነጽሑፍ የሚተላለፈው…',['በቃል ከትውልድ ወደ ትውልድ','በኮምፒውተር ብቻ','በጋዜጣ ብቻ']),A('"ድር ቢያብር አንበሳ ያስር" teaches…','"ድር ቢያብር አንበሳ ያስር" የሚያስተምረው…',['አንድነትን','ስንፍናን','ፍርሃትን']),A('"ዘርይሁን ለእናቱ ቀሚስ ገዛ" — indirect object?','"ዘርይሁን ለእናቱ ቀሚስ ገዛ" — ኢቀጥተኛ ተሳቢው?',['ለእናቱ','ቀሚስ','ገዛ']),A('Which is oral literature?','ቃላዊ ሥነጽሑፍ የትኛው ነው?',['እንቆቅልሽና ተረት','የሒሳብ መጽሐፍ','ካርታ'])],
 notes(('Oral literature (riddles, proverbs, tales, oral poems) carries wisdom across generations; sentences can have direct and indirect objects.','ቃላዊ ሥነጽሑፍ (እንቆቅልሽ፣ ምሳሌያዊ አነጋገር፣ ተረት፣ ቃላዊ ግጥም) ጥበብን ከትውልድ ወደ ትውልድ ያሸጋግራል፤ ዓረፍተ ነገር ቀጥተኛና ኢቀጥተኛ ተሳቢ ሊኖረው ይችላል።'),
  [('Oral literature is created and passed on by word of mouth.','ቃላዊ ሥነጽሑፍ በቃል ተፈጥሮ በቃል ይተላለፋል።'),('Kinds: work songs, fukera, wedding songs, riddles, proverbs, tales.','ዓይነቶች፦ የሥራ ዘፈን፣ ፉከራ፣ የሠርግ ዘፈን፣ እንቆቅልሽ፣ ምሳሌያዊ አነጋገር፣ ተረት።'),('Proverbs give advice: ድር ቢያብር አንበሳ ያስር.','ምሳሌያዊ አነጋገር ምክር ይሰጣል፦ ድር ቢያብር አንበሳ ያስር።'),('Direct object = what; indirect object = to whom (ለ-).','ቀጥተኛ ተሳቢ = ምን፤ ኢቀጥተኛ ተሳቢ = ለማን (ለ-)።')],
  [('ቃላዊ ሥነጽሑፍ','oral literature','በቃል የሚተላለፍ ሥነጽሑፍ'),('ምሳሌያዊ አነጋገር','proverb','አጭር ጥበብ ያለው አባባል'),('ተረት','folktale','በቃል የሚነገር ታሪክ')],('Wisdom lives in our proverbs.','ጥበብ በምሳሌያዊ አነጋገሮቻችን ውስጥ ይኖራል።'),
  [(('Give the meaning of "ያልሠራ አይብላ"','"ያልሠራ አይብላ" ፍቺ'),'ሳይሠሩ መብላት አይገባም'),(('Find the direct object: እናት ለልጇ ታሪክ አነበበች።','ቀጥተኛ ተሳቢውን ፈልጉ፦ እናት ለልጇ ታሪክ አነበበች።'),'ታሪክ')],
  (('Grandparents\' story podcast','የአያቶች ታሪክ ፖድካስት'),('Recording oral literature keeps it alive and can become a media project. Record an elder telling a tale or riddles.','ቃላዊ ሥነጽሑፍን መቅዳት ሕያው ያደርገዋል፤ የሚዲያ ፕሮጀክትም ሊሆን ይችላል። አንድ አረጋዊ ተረት ወይም እንቆቅልሽ ሲነግሩ ቅዱ።'),
   [('Ask permission and prepare questions.','ፈቃድ ጠይቁና ጥያቄዎችን አዘጋጁ።'),('Record with a phone (sound only is fine).','በስልክ ቅዱ (ድምፅ ብቻ በቂ ነው)።'),('Write down the tale and its lesson.','ተረቱንና ትምህርቱን ጻፉ።'),('Share it in class with the elder\'s name.','ከአረጋዊው ስም ጋር በክፍል አጋሩ።')])),
 sm(('Oral literature carries our wisdom','ቃላዊ ሥነጽሑፍ ጥበባችንን ይሸከማል'),[('Tales','ተረቶች'),('Riddles','እንቆቅልሾች'),('Proverbs','ምሳሌያዊ አነጋገሮች'),('Direct and indirect objects','ቀጥተኛና ኢቀጥተኛ ተሳቢ')]))
dump('am')
